### General syntax ########################################################################
# up by x1.5                <icon=fieldUp> <c=green>x1.5</c>
# down by 0.5               <icon=fieldDown> <c=red>x0.5</c>
# green                     <c=green></c>
# red                       <c=red></c>         (actually crimson bc funny) (hi ily)
# orange                    <c=orange></c>
# field general             <icon=field>
# field change              <icon=fieldChange>
# field up                  <icon=fieldUp>
# field down                <icon=fieldDown>
# field plus                <icon=fieldPlus>
# text-to-speech            <icon=fieldPlus,tts=\"and\">
# type boosted              PBFieldNote.new(:ELECTERRAIN,"<icon=typeELECTRIC> attacks <icon=fieldUp> <c=green>x1.5</c> when . . .", "...when attacker is grounded."),
# attacks boosted           PBFieldNote.new(:ELECTERRAIN,"Certain attacks <icon=fieldUp> <c=green>x1.5</c> . . .", FIELDEFFECTS.dig(:ELECTERRAIN, :damageMods, 1.5)),
# attacks weakened          PBFieldNote.new(:ELECTERRAIN,"Certain attacks <icon=fieldDown> <c=red>x0.5</c> . . .", FIELDEFFECTS.dig(:ELECTERRAIN, :damageMods, 0.5)),

# arguments for PBFieldNote are as follows:
# 1: which field the field note belongs to (first stage in case of fields with stages)
# 2: The text that's on screen explaining a field phenomenon
# 3: Elaboration on the field phenomenon if no space was left on screen (optional)
# 4: text that appears to the right which shows what stage of field it happens (optional)

